import openpyxl
from datetime import datetime

wb = openpyxl.load_workbook('task/init.xlsx')
rng = wb['RANGES']
lst = wb['LISTS']

def parse_date(v):
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, str):
        return datetime.strptime(v, '%m/%d/%Y').date()
    return None

# find sections in RANGES by header in column C
sections = {}
for r in range(1, rng.max_row+1):
    v = rng.cell(r,3).value
    if isinstance(v,str) and v in ('STAGE','DATA','OPERATION'):
        sections[v] = r

def compute(name):
    hdr = sections[name]
    groups = {}
    r = hdr + 2
    while r <= rng.max_row:
        d = parse_date(rng.cell(r,2).value)
        ref = rng.cell(r,4).value
        amt = rng.cell(r,5).value
        if d is None or ref is None or amt is None:
            break
        key = (d, ref)
        groups[key] = groups.get(key,0)+amt
        r += 1
    items = sorted(groups.items(), key=lambda kv:(kv[0][0], kv[0][1]))
    return items

for name, start_row, total_row in [('DATA',15,20), ('OPERATION',25,32)]:
    items = compute(name)
    for i,(key,amt) in enumerate(items):
        rr = start_row + i
        lst.cell(rr,2).value = datetime(key[0].year, key[0].month, key[0].day)
        lst.cell(rr,2).number_format = 'mm-dd-yy'
        lst.cell(rr,3).value = key[1]
        lst.cell(rr,4).value = amt
    lst.cell(total_row,4).value = f'=SUM(D{start_row}:D{start_row+len(items)-1})'

wb.save('task/output.xlsx')
print('done')
EOF
python3 task/fill.py
